docutils.frontend.validate_strip_class:
def validate_strip_class(setting: str, value: str | None = None, option_parser: OptionParser | None = None, config_parser: ConfigParser | None = None, config_section: str | None = None) -> list[str]:
    if value is None:
        value = setting
    value = validate_comma_separated_list(value)
    for cls in value:
        normalized = docutils.nodes.make_id(cls)
        if cls != normalized:
            raise ValueError('Invalid class value %r (perhaps %r?)' % (cls, normalized))
    return value

