def flag(argument: str) -> None:
    """
    Check for a valid flag option (no argument) and return ``None``.
    (Directive option conversion function.)

    Raise ``ValueError`` if an argument is found.
    """
    if (argument and argument.strip()):
        raise ValueError('no argument is allowed; "%s" supplied' % argument)
    else:
        return None

docutils.utils.__init__.clean_rcs_keywor:
def clean_rcs_keywords(paragraph: nodes.paragraph, keyword_substitutions: Sequence[tuple[re.Pattern[([str], str)]]]) -> None:
    if (len(paragraph) == 1 and isinstance(paragraph[0], nodes.Text)):
        textnode = paragraph[0]
        for (pattern, substitution) in keyword_substitutions:
            match = pattern.search(textnode)
            if match:
                paragraph[0] = nodes.Text(pattern.sub(substitution, textnode))
                return

docutils.core._name_arg_warning:
def _name_arg_warning(*name_args) -> None:
    for (component, name_arg) in zip(('reader', 'parser', 'writer'), name_args):
        if name_arg is not None:
            warnings.warn(f'Argument "{component}_name" will be removed in Docutils 2.0.  Specify {component} name in the "{component}" argument.', PendingDeprecationWarning, stacklevel=3)

